// ─── Pivot table (custom cross-tab rendered from REST API data) ───────────────

interface PivotCell { row: string; col: string; value: number; }

function PivotTableView({
  query, modelId, rowLabel, colLabel, metricLabel, showPct, runtimeDateFilter,
}: {
  query: string; modelId: string;
  rowLabel: string; colLabel: string; metricLabel: string; showPct?: boolean;
  runtimeDateFilter?: Record<string, unknown> | null;
}) {
  const [cells,    setCells]    = React.useState<PivotCell[]>([]);
  const [rowKeys,  setRowKeys]  = React.useState<string[]>([]);
  const [colKeys,  setColKeys]  = React.useState<string[]>([]);
  const [loading,  setLoading]  = React.useState(true);
  const [error,    setError]    = React.useState<string | null>(null);

  React.useEffect(() => {
    let cancelled = false;
    setLoading(true); setError(null);
    searchData({
      query_string: query,
      logical_table_identifier: modelId,
      data_format: 'COMPACT',
      record_size: 5000,
      ...(runtimeDateFilter ? { runtime_filter: runtimeDateFilter as any } : {}),
    })
      .then(resp => {
        if (cancelled) return;
        const colNames: string[] = resp?.contents?.[0]?.column_names ?? [];
        const rows: unknown[][] = (resp?.contents?.[0]?.data_rows as unknown as unknown[][]) ?? [];

        // Detect column indices by matching labels (fuzzy)
        const findIdx = (label: string) => {
          let i = colNames.findIndex(n => n.toLowerCase() === label.toLowerCase());
          if (i < 0) i = colNames.findIndex(n => n.toLowerCase().includes(label.toLowerCase()) || label.toLowerCase().includes(n.toLowerCase()));
          return i;
        };
        let rowIdx = findIdx(rowLabel);
        let colIdx = findIdx(colLabel);
        // measure = whichever column is numeric
        let valIdx = colNames.findIndex((_, i) => {
          if (i === rowIdx || i === colIdx) return false;
          return rows.slice(0, 5).some(r => typeof r[i] === 'number');
        });
        if (valIdx < 0) valIdx = colNames.findIndex((_, i) => i !== rowIdx && i !== colIdx);

        // If auto-detect failed, assign positionally
        if (rowIdx < 0) rowIdx = 0;
        if (colIdx < 0) colIdx = 1;
        if (valIdx < 0) valIdx = 2;

        const built: PivotCell[] = [];
        const rowSet = new Set<string>(); const colSet = new Set<string>();
        for (const r of rows) {
          const rv = r[rowIdx] != null ? String(r[rowIdx]) : '(blank)';
          const cv = r[colIdx] != null ? String(r[colIdx]) : '(blank)';
          const mv = typeof r[valIdx] === 'number' ? r[valIdx] as number : parseFloat(String(r[valIdx] ?? 0)) || 0;
          built.push({ row: rv, col: cv, value: mv });
          rowSet.add(rv); colSet.add(cv);
        }
        setRowKeys(Array.from(rowSet).sort());
        setColKeys(Array.from(colSet).sort());
        setCells(built);
        setLoading(false);
      })
      .catch(e => { if (!cancelled) { setError(String(e)); setLoading(false); } });
    return () => { cancelled = true; };
  }, [query, modelId, rowLabel, colLabel]);

  const fmt = (n: number) => {
    if (Math.abs(n) >= 1_000_000) return `${(n / 1_000_000).toFixed(1)}M`;
    if (Math.abs(n) >= 1_000)     return `${Math.round(n / 1_000)}K`;
    return Math.round(n).toLocaleString();
  };

  const lookup = React.useMemo(() => {
    const m: Record<string, number> = {};
    for (const c of cells) m[`${c.row}||${c.col}`] = c.value;
    return m;
  }, [cells]);

  const rowTotals   = React.useMemo(() => Object.fromEntries(rowKeys.map(r => [r, colKeys.reduce((s, c) => s + (lookup[`${r}||${c}`] ?? 0), 0)])), [rowKeys, colKeys, lookup]);
  const colTotals   = React.useMemo(() => Object.fromEntries(colKeys.map(c => [c, rowKeys.reduce((s, r) => s + (lookup[`${r}||${c}`] ?? 0), 0)])), [rowKeys, colKeys, lookup]);
  const grandTotal  = React.useMemo(() => rowKeys.reduce((s, r) => s + (rowTotals[r] ?? 0), 0), [rowKeys, rowTotals]);

  if (loading) return (
    <div style={{ padding: '2rem', display: 'flex', alignItems: 'center', gap: 10, color: 'rgba(0,0,0,0.45)', fontSize: 13 }}>
      <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke={BLUE} strokeWidth="2.5" strokeLinecap="round" style={{ animation: 'ts-spin 0.8s linear infinite', flexShrink: 0 }}>
        <path d="M12 2v4M12 18v4M4.93 4.93l2.83 2.83M16.24 16.24l2.83 2.83M2 12h4M18 12h4M4.93 19.07l2.83-2.83M16.24 7.76l2.83-2.83" />
      </svg>
      Building pivot table…
      <style>{`@keyframes ts-spin{from{transform:rotate(0deg)}to{transform:rotate(360deg)}}`}</style>
    </div>
  );
  if (error) return <div style={{ padding: '1.5rem', color: '#c00', fontSize: 12 }}>Pivot error: {error}</div>;
  if (cells.length === 0) return <div style={{ padding: '1.5rem', color: 'rgba(0,0,0,0.40)', fontSize: 13 }}>No data for this selection.</div>;

  const thStyle: React.CSSProperties = {
    padding: '7px 12px', fontSize: 11, fontWeight: 700, color: NAVY,
    backgroundColor: '#F0F6FB', border: '1px solid rgba(0,61,107,0.10)',
    whiteSpace: 'nowrap', textAlign: 'left', position: 'sticky', top: 0, zIndex: 2,
  };
  const tdStyle: React.CSSProperties = {
    padding: '6px 12px', fontSize: 12, color: '#2a2a2a',
    border: '1px solid rgba(0,61,107,0.07)', textAlign: 'right', whiteSpace: 'nowrap',
  };
  const totalStyle: React.CSSProperties = {
    ...tdStyle, fontWeight: 700, backgroundColor: 'rgba(0,159,227,0.06)', color: NAVY,
  };

  return (
    <div style={{ overflowX: 'auto', overflowY: 'auto', maxHeight: '58vh' }}>
      <table style={{ borderCollapse: 'collapse', fontSize: 12, width: '100%' }}>
        <thead>
          <tr>
            <th style={{ ...thStyle, textAlign: 'left', minWidth: 140, position: 'sticky', left: 0, zIndex: 3, backgroundColor: '#EAF5FC' }}>
              {rowLabel} ↓ / {colLabel} →
            </th>
            {colKeys.map(c => <th key={c} style={thStyle}>{c}</th>)}
            <th style={{ ...thStyle, backgroundColor: 'rgba(0,159,227,0.10)' }}>Total</th>
          </tr>
        </thead>
        <tbody>
          {rowKeys.map((row, ri) => (
            <tr key={row} style={{ backgroundColor: ri % 2 === 0 ? '#FFFFFF' : 'rgba(0,61,107,0.015)' }}>
              <td style={{ ...tdStyle, textAlign: 'left', fontWeight: 600, color: NAVY, position: 'sticky', left: 0, backgroundColor: ri % 2 === 0 ? '#FFFFFF' : '#F7FAFD', zIndex: 1 }}>
                {row}
              </td>
              {colKeys.map(col => {
                const v    = lookup[`${row}||${col}`] ?? 0;
                const pct  = colTotals[col] > 0 ? v / colTotals[col] : 0;
                const disp = showPct
                  ? (v > 0 ? `${(pct * 100).toFixed(1)}%` : <span style={{ color: 'rgba(0,0,0,0.20)' }}>–</span>)
                  : (v > 0 ? fmt(v) : <span style={{ color: 'rgba(0,0,0,0.20)' }}>–</span>);
                return (
                  <td key={col} style={tdStyle}>
                    <div style={{ position: 'relative' }}>
                      <div style={{ position: 'absolute', left: 0, bottom: 0, height: 2, width: `${pct * 100}%`, backgroundColor: 'rgba(0,159,227,0.35)', borderRadius: 1 }} />
                      {disp}
                    </div>
                  </td>
                );
              })}
              <td style={totalStyle}>
                {showPct
                  ? `${grandTotal > 0 ? ((rowTotals[row] ?? 0) / grandTotal * 100).toFixed(1) : 0}%`
                  : fmt(rowTotals[row] ?? 0)}
              </td>
            </tr>
          ))}
          <tr style={{ borderTop: `2px solid rgba(0,61,107,0.15)` }}>
            <td style={{ ...totalStyle, textAlign: 'left', position: 'sticky', left: 0, zIndex: 1 }}>Total</td>
            {colKeys.map(col => <td key={col} style={totalStyle}>{fmt(colTotals[col] ?? 0)}</td>)}
            <td style={{ ...totalStyle, backgroundColor: 'rgba(0,159,227,0.15)' }}>{fmt(grandTotal)}</td>
          </tr>
        </tbody>
      </table>
    </div>
  );
}

// ─── Flat Table with % of Total (used when calcType === 'pct' + Table mode) ──
interface FlatRow { dim: string; value: number }

function FlatTablePctView({
  query, modelId, dimLabel, metricLabel, runtimeDateFilter,
}: {
  query: string; modelId: string;
  dimLabel: string; metricLabel: string;
  runtimeDateFilter?: Record<string, unknown> | null;
}) {
  const [rows,    setRows]    = React.useState<FlatRow[]>([]);
  const [loading, setLoading] = React.useState(true);
  const [error,   setError]   = React.useState<string | null>(null);

  React.useEffect(() => {
    let cancelled = false;
    setLoading(true); setError(null);
    searchData({
      query_string: query,
      logical_table_identifier: modelId,
      data_format: 'COMPACT',
      record_size: 5000,
      ...(runtimeDateFilter ? { runtime_filter: runtimeDateFilter as any } : {}),
    })
      .then(resp => {
        if (cancelled) return;
        const colNames: string[] = resp?.contents?.[0]?.column_names ?? [];
        const rawRows: unknown[][] = (resp?.contents?.[0]?.data_rows as unknown as unknown[][]) ?? [];

        // Find numeric (metric) column and the first string (dimension) column
        const findIdx = (label: string) => {
          let i = colNames.findIndex(n => n.toLowerCase() === label.toLowerCase());
          if (i < 0) i = colNames.findIndex(n =>
            n.toLowerCase().includes(label.toLowerCase()) || label.toLowerCase().includes(n.toLowerCase()));
          return i;
        };
        let dimIdx = findIdx(dimLabel);
        let valIdx = colNames.findIndex((_, i) => {
          if (i === dimIdx) return false;
          return rawRows.slice(0, 5).some(r => typeof r[i] === 'number');
        });
        if (dimIdx < 0) dimIdx = 0;
        if (valIdx < 0) valIdx = colNames.length > 1 ? 1 : 0;

        const built: FlatRow[] = rawRows.map(r => ({
          dim:   r[dimIdx] != null ? String(r[dimIdx]) : '(blank)',
          value: typeof r[valIdx] === 'number' ? r[valIdx] as number
                 : parseFloat(String(r[valIdx] ?? 0)) || 0,
        }));
        // Sort descending by value
        built.sort((a, b) => b.value - a.value);
        setRows(built);
        setLoading(false);
      })
      .catch(e => { if (!cancelled) { setError(String(e)); setLoading(false); } });
    return () => { cancelled = true; };
  }, [query, modelId, dimLabel, metricLabel]);

  const fmt = (n: number) => {
    if (Math.abs(n) >= 1_000_000) return `£${(n / 1_000_000).toFixed(2)}M`;
    if (Math.abs(n) >= 1_000)     return `£${Math.round(n / 1_000).toLocaleString()}K`;
    return `£${Math.round(n).toLocaleString()}`;
  };

  const grandTotal = React.useMemo(() => rows.reduce((s, r) => s + r.value, 0), [rows]);

  if (loading) return (
    <div style={{ padding: '2rem', display: 'flex', alignItems: 'center', gap: 10, color: 'rgba(0,0,0,0.45)', fontSize: 13 }}>
      <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke={BLUE} strokeWidth="2.5" strokeLinecap="round"
        style={{ animation: 'ts-spin 0.8s linear infinite', flexShrink: 0 }}>
        <path d="M12 2v4M12 18v4M4.93 4.93l2.83 2.83M16.24 16.24l2.83 2.83M2 12h4M18 12h4M4.93 19.07l2.83-2.83M16.24 7.76l2.83-2.83" />
      </svg>
      Calculating percentages…
      <style>{`@keyframes ts-spin{from{transform:rotate(0deg)}to{transform:rotate(360deg)}}`}</style>
    </div>
  );
  if (error)        return <div style={{ padding: '1.5rem', color: '#c00', fontSize: 12 }}>Error: {error}</div>;
  if (rows.length === 0) return <div style={{ padding: '1.5rem', color: 'rgba(0,0,0,0.40)', fontSize: 13 }}>No data for this selection.</div>;

  const thStyle: React.CSSProperties = {
    padding: '8px 14px', fontSize: 11, fontWeight: 700, color: NAVY,
    backgroundColor: '#F0F6FB', border: '1px solid rgba(0,61,107,0.10)',
    whiteSpace: 'nowrap', textAlign: 'left', position: 'sticky', top: 0, zIndex: 2,
  };
  const tdStyle: React.CSSProperties = {
    padding: '7px 14px', fontSize: 12, color: '#2a2a2a',
    border: '1px solid rgba(0,61,107,0.07)', whiteSpace: 'nowrap',
  };
  const totalRow: React.CSSProperties = {
    ...tdStyle, fontWeight: 700, backgroundColor: 'rgba(0,159,227,0.06)', color: NAVY,
  };

  return (
    <div style={{ overflowX: 'auto', overflowY: 'auto', maxHeight: '58vh' }}>
      <table style={{ borderCollapse: 'collapse', fontSize: 12, width: '100%' }}>
        <thead>
          <tr>
            <th style={{ ...thStyle, minWidth: 160 }}>{dimLabel}</th>
            <th style={{ ...thStyle, textAlign: 'right' }}>{metricLabel}</th>
            <th style={{ ...thStyle, textAlign: 'right' }}>% of Total</th>
            <th style={{ ...thStyle, minWidth: 120 }}>Share</th>
          </tr>
        </thead>
        <tbody>
          {rows.map((row, ri) => {
            const pct = grandTotal > 0 ? row.value / grandTotal : 0;
            return (
              <tr key={row.dim} style={{ backgroundColor: ri % 2 === 0 ? '#FFFFFF' : 'rgba(0,61,107,0.015)' }}>
                <td style={{ ...tdStyle, fontWeight: 600, color: NAVY }}>{row.dim}</td>
                <td style={{ ...tdStyle, textAlign: 'right' }}>{fmt(row.value)}</td>
                <td style={{ ...tdStyle, textAlign: 'right', fontWeight: 600, color: BLUE }}>
                  {(pct * 100).toFixed(1)}%
                </td>
                <td style={{ ...tdStyle, padding: '7px 10px' }}>
                  <div style={{
                    height: 10, borderRadius: 5, width: `${Math.max(pct * 100, 0.5)}%`,
                    backgroundColor: BLUE, opacity: 0.55,
                    transition: 'width 0.4s ease',
                  }} />
                </td>
              </tr>
            );
          })}
        </tbody>
        <tfoot>
          <tr style={{ borderTop: `2px solid rgba(0,61,107,0.15)` }}>
            <td style={{ ...totalRow, textAlign: 'left' }}>Total</td>
            <td style={{ ...totalRow, textAlign: 'right' }}>{fmt(grandTotal)}</td>
            <td style={{ ...totalRow, textAlign: 'right' }}>100%</td>
            <td style={totalRow} />
          </tr>
        </tfoot>
      </table>
    </div>
  );
}

